(()=>{'use strict';
const $=id=>document.getElementById(id),el=(tag,value)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=String(value);return n};
const session=()=>{try{return sessionStorage.getItem('owg_dashboard_session_v1')||'';}catch(_){return '';}};
const base='/v1/enterprise-connectors/bundle-import',max=16*1024*1024;
let report=null,selectedFile=null,requestId=null,busy=false;
function table(rows){const t=el('table'),b=el('tbody');for(const [k,v] of rows){const tr=el('tr'),th=el('th',k);th.scope='row';tr.append(th,el('td',v===null||v===undefined?'—':typeof v==='object'?JSON.stringify(v):v));b.append(tr);}t.append(b);return t;}
function controls(){const file=$('file').files[0];$('preview').disabled=busy||!file||file.size<1||file.size>max||!$('inspectConsent').checked;$('retain').disabled=busy||!report||!$('origin').checked||!$('retention').checked||(!$('target').value&&!$('name').value.trim());$('refresh').disabled=busy;$('nameLabel').hidden=!!$('target').value;}
function invalidate(){report=null;selectedFile=null;requestId=null;$('reviewPanel').hidden=true;$('review').replaceChildren();$('origin').checked=$('retention').checked=false;controls();}
function clear(){invalidate();$('file').value='';$('logs').replaceChildren();$('history').replaceChildren();$('target').replaceChildren(new Option('Create new mining log',''));$('inspectConsent').checked=false;controls();}
async function api(path,body,headers={}){const token=session();if(!token)throw Error('Local dashboard session missing. Reopen OWG from its launcher.');const r=await fetch(path,{method:body===undefined?'GET':'POST',body,headers:{Authorization:'OWG-Session '+token,...headers},credentials:'same-origin',cache:'no-store'});if(token!==session()){clear();throw Error('Local session changed; response discarded.');}if(r.status===401||r.status===403){clear();throw Error('Local session or explicit approval required.');}const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Local import request failed');if(token!==session()){clear();throw Error('Local session changed; response discarded.');}return data;}
async function action(fn){if(busy)return;busy=true;const fields=[...document.querySelectorAll('input,select')].map(n=>[n,n.disabled]);for(const [n] of fields)n.disabled=true;controls();try{await fn();}catch(e){$('status').textContent=e.message;}finally{for(const [n,d] of fields)n.disabled=d;busy=false;controls();}}
function render(r){const rows=[['Exact file SHA-256',r.file_sha256],['Canonical bundle SHA-256',r.canonical_bundle_sha256],['Events',r.event_count],['Source-local cases',r.source_local_case_count],['Activity labels present',r.activity_labels_present],['Business-date evidence present',r.business_date_evidence_present],['Manifest and row consistency',r.manifest_and_row_integrity_verified],['Origin authenticated',r.gateway_origin_authenticated],['Live grants verified',r.live_grants_verified],['Target',r.target_log_id??'New local log'],['Target revision',r.expected_target_revision],['Already imported',r.bundle_already_imported??false]];
const nodes=[table(rows)];for(const s of r.sources){const a=el('article');a.append(el('h3',s.manifest.provider+' · '+s.job_id),table([['Grant',s.grant_id],['Manifest SHA-256',s.manifest_sha256],['Profile revision',s.manifest.profile_revision],['Activity mode',s.manifest.activity_mode],['Event time window',s.manifest.since+' — '+s.manifest.until],['Source change checkpoint',s.manifest.checkpoint],['Events',s.manifest.event_count],['Cases',s.manifest.case_count]]));nodes.push(a);}$('review').replaceChildren(...nodes);$('reviewPanel').hidden=false;}
async function load(){const current=$('target').value;const r=await api(base);const opts=[new Option('Create new mining log','')],nodes=[];for(const log of r.logs){const p=log.connector_bundle_import;opts.push(new Option(log.name+' · '+log.log_id,log.log_id));const a=el('article'),b=el('button','View import receipts');b.type='button';b.onclick=()=>action(async()=>{const r=await api(base+'/'+encodeURIComponent(log.log_id)+'/receipts');const nodes=[el('h3',r.log.name+' · import receipts')];for(const entry of r.receipts)nodes.push(table([['Revision',entry.revision],['Canonical bundle SHA-256',entry.canonical_bundle_sha256],['Events added',entry.events_added],['Duplicates skipped',entry.duplicates_skipped],['Retained events',entry.retained_event_count],['Source manifests',entry.sources.map(x=>x.manifest_sha256)]]));$('history').replaceChildren(...nodes);});
a.append(el('h3',log.name),table([['Log ID',log.log_id],['Current events',log.events],['Last receipt event count',p.events_after_last_verified_import],['Receipt revision',p.revision],['Current event count matches receipt',p.current_event_count_matches_last_receipt]]),b);nodes.push(a);}$('target').replaceChildren(...opts);if(opts.some(x=>x.value===current))$('target').value=current;else invalidate();$('logs').replaceChildren(...(nodes.length?nodes:[el('p','No verified bundle logs yet.')]));controls();}
$('file').onchange=$('target').onchange=$('inspectConsent').onchange=invalidate;$('name').oninput=()=>{requestId=null;$('retention').checked=false;controls();};$('origin').onchange=$('retention').onchange=controls;
$('preview').onclick=()=>action(async()=>{invalidate();const file=$('file').files[0];if(!file||file.size<1||file.size>max||!$('inspectConsent').checked)throw Error('Select a bounded JSON bundle and approve inspection.');const params=new URLSearchParams();if($('target').value)params.set('target',$('target').value);const r=await api(base+'/preview?'+params,file,{'Content-Type':'application/json','X-OWG-Bundle-Inspection-Confirmed':'true'});selectedFile=file;report=r;requestId=null;render(r);$('status').textContent='Exact file validated. No evidence retained.';});
$('retain').onclick=()=>action(async()=>{if(!report||selectedFile!==$('file').files[0]||!$('origin').checked||!$('retention').checked||($('target').value||null)!==report.target_log_id)throw Error('Review the exact file and destination first.');const params=new URLSearchParams({expected_revision:String(report.expected_target_revision)});if(report.target_log_id)params.set('target',report.target_log_id);else params.set('name',$('name').value);if(!requestId)requestId=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');const r=await api(base+'/retain?'+params,selectedFile,{'Content-Type':'application/json','X-OWG-Local-Storage-Confirmed':'true','X-OWG-Bundle-Origin-Reviewed':'true','X-OWG-Bundle-File-SHA256':report.file_sha256,'X-OWG-Bundle-Canonical-SHA256':report.canonical_bundle_sha256,'X-OWG-Bundle-Request-ID':requestId});invalidate();await load();$('status').textContent=(r.replayed_receipt?'Existing receipt: ':'Bundle retained: ')+r.log.name+' · '+r.receipt.events_added+' added, '+r.receipt.duplicates_skipped+' duplicates in original receipt.';});
$('refresh').onclick=()=>action(async()=>{invalidate();$('history').replaceChildren();await load();});window.addEventListener('pagehide',clear);action(load);
})();